import{z as o,x as s,o as t,c as d,q as B,j as i,D as A,d as e,s as l,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"事件研究","description":"","frontmatter":{"title":"事件研究","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/event-study-econ.md","filePath":"econ/event-study-econ.md","lastUpdated":1791413859000}'),p={name:"econ/event-study-econ.md"};function m(u,a,D,T,c,h){const n=s("Mermaid");return t(),d("div",null,[a[2]||(a[2]=B('<h1 id="事件研究" tabindex="-1">事件研究 <a class="header-anchor" href="#事件研究" aria-label="Permalink to &quot;事件研究&quot;">​</a></h1><div class="epigraph"><p>把日历对齐到事件日，估计的是一条相对路径：前期该在零附近，后期才是动态效应。路径能画出来，不等于反事实已经被识别。</p><footer>—— MacKinlay, Event Studies in Economics and Finance, Journal of Economic Literature 1997；对照 Angrist and Pischke；Sun and Abraham 对交错采纳事件系数的分解</footer></div><p><a href="/econ/matching-propensity">上一课</a>在可观测 \\(X\\) 上重建截面对照：CIA 加重叠，给出支撑上的 ATT。本课不重估倾向得分，也不把平衡表再做一遍。缺口是时间锚定：政策、判决或公告落在已知日期，能否用事件前后的窗口读「异常路径」？匹配回答谁和谁比；事件研究回答相对 \\(t=0\\) 哪一段动了。后课<a href="/econ/structural-vs-reduced">结构对约化形式</a>会问这条路径能不能外推到从未发生的规则；本课先钉约化形式事件系数本身要什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>相对事件日 \\(k\\)，常见回归是</p> \\[Y_{it}=\\alpha_i+\\lambda_t+\\sum_{k\\neq -1}\\beta_k\\mathbf{1}\\{t=e_i+k\\}+\\varepsilon_{it}, \\]<p>省略 \\(k=-1\\) 作参照。\\(\\beta_k\\) 是「相对事件前一期」的平均差。要把它读成动态处理效应，至少要：无预期（\\(k\\lt 0\\) 时 \\(\\beta_k\\approx 0\\)）、窗口内无重叠混淆事件、处理时点不是结果自己选出来的。匹配的 CIA 是截面选择；这里的平行趋势是<strong>反事实 \\(Y(0)\\) 在事件对齐后仍与对照同走</strong>。预趋势可以证伪，不能证实——与 DiD 同一句，只是展示改成路径。</p><p>金融传统里，MacKinlay 的异常收益 \\(AR_{it}=R_{it}-\\mathbb{E}[R_{it}\\mid\\mathcal{I}_{t-1}]\\)，CAR 是窗口求和。信息含量检验问的是公告是否未预期；政策事件研究问的是干预的动态 ATT。同名，对象不同，识别句却共用「预期与混淆」。</p><p><span class="marginnote">术语翻译：TWFE（双向固定效应）就是同时扣掉两套「天生差异」——每个单位自己的平均水平（企业固定效应）和每一期的共同波动（时间固定效应），剩下的事件前后之差才归给政策。回归里那串 \\(\\alpha_i+\\lambda_t\\) 就是这两把扣除。</span></p><h3 id="前期系数为零不是识别证明" tabindex="-1">前期系数为零不是识别证明 <a class="header-anchor" href="#前期系数为零不是识别证明" aria-label="Permalink to &quot;前期系数为零不是识别证明&quot;">​</a></h3><p>把事件图上 \\(k\\lt 0\\) 的置信区间盖住零，写成「所以平行趋势成立」，是把必要诊断当成充分条件。检验功效可以很低；预期若刚好在 \\(k=-1\\) 才进入，参照期本身已污染。金融里提前泄露会把效应提前打进价格，政策里会把行为提前打进 \\(Y\\)——前期不零，往往是设计坏了，不是「还有一个负效应」。</p><p><span class="marginnote">资产定价的事件研究用市场模型估预期收益；劳动与公共财政用 TWFE 事件虚拟变量。本课两种都点，后文默认政策路径，金融 CAR 只作对照，不进限价簿。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>金融：估计窗拟合市场模型，事件窗算 \\(AR\\)/\\(CAR\\)，横截面或时间聚类 SE。政策：两期两组时事件系数退回 DiD；交错采纳下，Sun–Abraham 等指出 TWFE 的 \\(\\beta_k\\) 可能是已被处理队列对尚未处理队列的污染加权。干净做法是队列特定路径或填补估计量——细节在交错 DiD 课，本课只禁止把一张 TWFE 事件图当成无污染 ATT。推断：冲击在企业则企业聚类；州政策则州聚类，接住<a href="/econ/clustered-se">聚类标准误</a>。</p>',14)),(t(),i(r,null,{default:A(()=>[l(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20MATCH%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E6%88%AA%E9%9D%A2%20CIA%20%E5%8C%B9%E9%85%8D%22%5D%20--%3E%20TIME%5B%22%E6%9C%AC%E8%AF%BE%3A%20%E5%AF%B9%E9%BD%90%E5%88%B0%E4%BA%8B%E4%BB%B6%E6%97%A5%22%5D%0A%20%20TIME%20--%3E%20PRE%5B%22k%20%E5%B0%8F%E4%BA%8E%200%3A%20%E5%BA%94%E5%9C%A8%E9%9B%B6%E9%99%84%E8%BF%91%22%5D%0A%20%20TIME%20--%3E%20POST%5B%22k%20%E5%A4%A7%E4%BA%8E%200%3A%20%E5%8A%A8%E6%80%81%E8%B7%AF%E5%BE%84%22%5D%0A%20%20PRE%20--%3E%20ANT%5B%22%E6%97%A0%E9%A2%84%E6%9C%9F%20%2F%20%E6%97%A0%E6%B3%84%E9%9C%B2%22%5D%0A%20%20POST%20--%3E%20RED%5B%22%E7%BA%A6%E5%8C%96%E5%BD%A2%E5%BC%8F%E5%8A%A8%E6%80%81%20ATT%22%5D%0A%20%20RED%20--%3E%20STR%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E8%83%BD%E5%90%A6%E5%A4%96%E6%8E%A8%E5%88%B0%E6%96%B0%E8%A7%84%E5%88%99%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"重叠窗口：同一单位多次事件，要把日历排开或只留首次。坏控制：不要把事件后才实现的中介放进回归右侧。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"力量在对齐：把异质日历收成相对时间，让「处理前」成为可画的对照。弱点也在对齐：预期把 \\(t=0\\) 提前，路径的零点就不是政策日。Bunching、立法通过日与生效日分离，都是同一机制的变体。匹配丢掉无法配对的单位；事件研究丢掉无法对齐的日历——都是用内部有效换样本。",-1)),a[6]||(a[6]=E("p",null,[e("与合成控制：合成控制给"),E("strong",null,"一个"),e("处理单位一条反事实路径；事件研究给"),E("strong",null,"许多"),e("单位一条平均路径。前者怕凸包外推，后者怕污染加权与预期。不要把两种图叠成「所以因果已经齐了」。")],-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"MacKinlay 1997 把金融事件研究收成估计窗、事件窗、原假设（均值 AR 为零）。政策文献把同一时间结构接到潜在结果：\\(\\beta_k=\\mathbb{E}[Y(1)-Y(0)\\mid k]\\) 只在上述假设下成立。")],-1)),(t(),i(r,null,{default:A(()=>[l(n,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALIGN%5B%22%E5%AF%B9%E9%BD%90%3A%20%E5%BC%82%E8%B4%A8%E6%97%A5%E5%8E%86%E6%94%B6%E6%88%90%E7%9B%B8%E5%AF%B9%E6%97%B6%E9%97%B4%20k%22%5D%20--%3E%20GOOD%5B%22%E5%A4%84%E7%90%86%E5%89%8D%E6%88%90%E4%B8%BA%E5%8F%AF%E7%94%BB%E7%9A%84%E5%AF%B9%E7%85%A7%22%5D%0A%20%20GOOD%20--%3E%20OK%5B%22k%20%E5%B0%8F%E4%BA%8E%200%20%E7%9B%96%E4%BD%8F%E9%9B%B6%3A%20%E8%AF%8A%E6%96%AD%E9%80%9A%E8%BF%87%22%5D%0A%20%20ALIGN%20--%3E%20ANT%5B%22%E9%A2%84%E6%9C%9F%E6%8F%90%E5%89%8D%3A%20%E8%A1%8C%E4%B8%BA%E7%A7%BB%E5%88%B0%20k%3D-1%20%E4%B9%8B%E5%89%8D%22%5D%0A%20%20ANT%20--%3E%20POLL%5B%22%E5%8F%82%E7%85%A7%E6%9C%9F%E8%A2%AB%E6%B1%A1%E6%9F%93%2C%20%E9%9B%B6%E7%82%B9%E5%A4%B1%E7%9C%9F%22%5D%0A%20%20ALIGN%20--%3E%20OVER%5B%22%E7%AA%97%E5%8F%A3%E9%87%8D%E5%8F%A0%3A%20%E5%A4%9A%E6%AC%A1%E4%BA%8B%E4%BB%B6%E6%B7%B7%E5%85%A5%22%5D%0A%20%20OVER%20--%3E%20MIX%5B%22%E7%B3%BB%E6%95%B0%E6%88%90%E6%B7%B7%E5%90%88%E7%89%A9%2C%20%E4%B8%8D%E6%98%AF%E5%B9%B2%E5%87%80%20ATT%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=B('<p><span class="marginnote">数字实例：公告日某股涨 3%，市场模型说它当天「本该」涨 0.5%，异常收益 AR = 2.5%；把公告窗三天的 AR 逐日加总就是 CAR。统计检验问的是：扣除正常回报后，这几天的累计超额是否显著异于零。</span></p><p><span class="marginnote">常见误区：「前期系数都盖住零 = 平行趋势成立」。检验功效低（样本少、置信区间宽）时盖住零什么也说明不了；若预期恰好提前一期进入，\\(k=-1\\) 的参照期本身已被污染。预趋势检查只能证伪识别，永远不能证实它。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 BLP、动态博弈的反事实价格写成事件系数。事件路径是给定制度下的约化形式；「若禁止这种合并、税率改成从未出现的课表」是下一课结构问题。也不重写交错 DiD 的全部加权公式。量化栏并购套利用另一套公告窗，本课不搬交易规则。</p><p>后课默认：事件图是诊断加动态 ATT 的展示；前期系数是可证伪检查。读路径时声明参照期、聚类层级、以及是否交错污染。结构参数不要从 \\(\\beta_k\\) 里直接读出来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>事件研究估相对 \\(t=0\\) 的路径，不是自动的因果证明。</li><li>识别要无预期、无混淆、时点外生；预趋势可证伪不可证实。</li><li>金融 CAR 与政策动态 ATT 同名不同物，共享预期问题。</li><li>交错 TWFE 事件系数可能污染，不能当干净权重。</li><li>路径是约化形式；从未出现的规则交给结构课。</li><li>出处：MacKinlay, <em>JEL</em> 1997；Angrist and Pischke；Sun and Abraham。</li></ul>',7))])}const F=o(p,[["render",m]]);export{k as __pageData,F as default};
